def capabilities_for_operation(operation: OperationId) -> tuple[CapabilityId, ...]:
    """Return the exact built-in capabilities required by an operation."""
    return OPERATION_CAPABILITIES[operation]


def operation_supports_target(
    operation: OperationId,
    *,
    target: str,
    platform: str,
    architecture: str,
    python_version: str,
) -> bool:
    """Return whether an operation is declared for one target cell."""
    if target not in SUPPORTED_EXECUTION_TARGETS:
        return False
    if platform not in SUPPORTED_TARGET_PLATFORMS:
        return False
    if architecture not in SUPPORTED_TARGET_ARCHITECTURES:
        return False
    if python_version not in SUPPORTED_TARGET_PYTHON_VERSIONS:
        return False
    targets = OPERATION_TARGETS.get(operation, ())
    platforms = OPERATION_PLATFORMS.get(operation, ())
    architectures = OPERATION_ARCHITECTURES.get(operation, ())
    python_versions = OPERATION_PYTHON_VERSIONS.get(operation, ())
    return (
        (not targets or target in targets)
        and (not platforms or platform in platforms)
        and (not architectures or architecture in architectures)
        and (not python_versions or python_version in python_versions)
    )


def capabilities_for_tier(name: str) -> tuple[str, ...] | None:
    """Return flattened grants, or ``None`` for an unknown tier."""
    return CAPABILITY_TIERS.get(name.strip().casefold())
